# ---------- 枚举型字段全等校验（§3.114a 硬守卫） ----------
TRACKS_OK = {'宏观', '其他/宽基', '大消费', 'A股医药', '美股标普医药', '恒生科技'}
CATS_OK = {'政策类', '业绩类', '行业事件类', '宏观类'}
bad_t = sorted({x['track'] for x in N} - TRACKS_OK)
bad_c = sorted({x['category'] for x in N} - CATS_OK)
if bad_t:
    raise SystemExit(f'❌ §3.114a 硬守卫：track 含未登记枚举值 {bad_t}')
if bad_c:
    raise SystemExit(f'❌ §3.114a 硬守卫：category 含未登记枚举值 {bad_c}')
for x in N:
    if 'window' in x:
        raise SystemExit('❌ window 应由本脚本统一写入，禁止逐条硬编码')
    x['window'] = WIN

# 标题前 20 字唯一性（供 sentiment 规则表前缀绑定，§3.129d）
pref = [x['title'][:20] for x in N]
dup = [p for p, c in Counter(pref).items() if c > 1]
if dup:
    raise SystemExit(f'❌ 标题前 20 字不唯一（§3.129d）: {dup}')

os.makedirs(os.path.dirname(NEWS), exist_ok=True)
json.dump(N, open(NEWS, 'w', encoding='utf-8'), ensure_ascii=False, indent=1)
print(f'✅ news-intraday-{TODAY}.json 写入 {len(N)} 条，window = {WIN}')
print('  赛道分布:', dict(Counter(x['track'] for x in N)))
print('  分类分布:', dict(Counter(x['category'] for x in N)))
print('  前缀唯一性: OK')
print('  前缀键清单（供 sentiment RULE 表逐字复制）:')
for x in N:
    print('   ', repr(x['title'][:20]))
